import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';
import AddCameraModal from './AddCameraModal';

export default function TopBar({ activePage, setActivePage }) {
  const { stats, alerts, wsConnected } = useApp();
  const [time,      setTime]      = useState('');
  const [showModal, setShowModal] = useState(false);
  const [showMenu,  setShowMenu]  = useState(false);

  const unreadAlerts = alerts.filter(a => !a.acknowledged).length;

  useEffect(() => {
    const tick = () => {
      const n       = new Date();
      let h         = n.getHours();
      let m         = n.getMinutes();
      let s         = n.getSeconds();
      const ap      = h >= 12 ? 'PM' : 'AM';
      h             = h % 12 || 12;
      const p       = v => v.toString().padStart(2, '0');
      const months  = ['Jan','Feb','Mar','Apr','May','Jun',
                       'Jul','Aug','Sep','Oct','Nov','Dec'];
      setTime(
        `${months[n.getMonth()]} ${n.getDate()}, ${n.getFullYear()}` +
        `  |  ${p(h)}:${p(m)}:${p(s)} ${ap}`
      );
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  return (
    <>
      <div style={{
        display:        'flex',
        alignItems:     'center',
        justifyContent: 'space-between',
        padding:        '10px 20px',
        borderBottom:   '1px solid #1e2d47',
        background:     '#111827',
        flexShrink:     0,
        height:         54
      }}>

        {/* ── Left — Logo ───────────────────────────────── */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          {/* Shield icon */}
          <div style={{
            width:        32, height: 32,
            borderRadius: '50%',
            border:       '2px solid #3b82f6',
            display:      'flex',
            alignItems:   'center',
            justifyContent: 'center',
            flexShrink:   0
          }}>
            <span style={{ fontSize: 16, color: '#3b82f6' }}>🛡</span>
          </div>
          <span style={{
            fontSize:      15,
            fontWeight:    700,
            color:         '#3b82f6',
            letterSpacing: '.5px'
          }}>
            BRAWL DETECTION SYSTEM
          </span>
          {/* Live badge */}
          <span style={{
            fontSize:     10,
            background:   wsConnected ? '#0d2010' : '#2d0a0a',
            color:        wsConnected ? '#4ade80' : '#f87171',
            padding:      '2px 8px',
            borderRadius: 10,
            fontWeight:   600,
            border:       `1px solid ${wsConnected ? '#166534' : '#7f1d1d'}`
          }}>
            ● {wsConnected ? 'LIVE' : 'OFFLINE'}
          </span>
        </div>

        {/* ── Right ─────────────────────────────────────── */}
        <div style={{
          display:    'flex',
          alignItems: 'center',
          gap:        20
        }}>
          {/* Clock */}
          <span style={{ fontSize: 13, color: '#94a3b8' }}>
            {time}
          </span>

          {/* Bell */}
          <div
            style={{ position: 'relative', cursor: 'pointer' }}
            onClick={() => window.dispatchEvent(
              new CustomEvent('navigate', { detail: 'Alerts' })
            )}
          >
            <span style={{ fontSize: 20, color: '#94a3b8' }}>🔔</span>
            {unreadAlerts > 0 && (
              <span style={{
                position:       'absolute',
                top:            -5, right: -5,
                background:     '#ef4444',
                color:          '#fff',
                fontSize:       9,
                fontWeight:     700,
                width:          17, height: 17,
                borderRadius:   '50%',
                display:        'flex',
                alignItems:     'center',
                justifyContent: 'center',
                border:         '2px solid #111827'
              }}>
                {unreadAlerts > 9 ? '9+' : unreadAlerts}
              </span>
            )}
          </div>

          {/* Admin */}
          <div style={{ position: 'relative' }}>
            <div
              onClick={() => setShowMenu(!showMenu)}
              style={{
                display:      'flex',
                alignItems:   'center',
                gap:          8,
                cursor:       'pointer',
                padding:      '5px 10px',
                borderRadius: 8,
                background:   showMenu ? '#1e2d47' : 'transparent',
                border:       '1px solid transparent',
                transition:   'all .2s'
              }}
              onMouseEnter={e => e.currentTarget.style.background = '#1e2d47'}
              onMouseLeave={e => {
                if (!showMenu) e.currentTarget.style.background = 'transparent';
              }}
            >
              {/* Avatar */}
              <div style={{
                width:          32, height: 32,
                borderRadius:   '50%',
                background:     '#1e3a5f',
                display:        'flex',
                alignItems:     'center',
                justifyContent: 'center',
                fontSize:       14, fontWeight: 700,
                color:          '#60a5fa',
                flexShrink:     0
              }}>
                A
              </div>
              <span style={{ fontSize: 13, color: '#e2e8f0', fontWeight: 500 }}>
                Admin
              </span>
              <span style={{ fontSize: 11, color: '#64748b' }}>▾</span>
            </div>

            {/* Dropdown */}
            {showMenu && (
              <div style={{
                position:     'absolute',
                top:          '110%', right: 0,
                background:   '#0f172a',
                border:       '1px solid #253550',
                borderRadius: 10,
                overflow:     'hidden',
                zIndex:       500,
                minWidth:     180,
                boxShadow:    '0 8px 30px rgba(0,0,0,.8)'
              }}>
                {/* Profile info */}
                <div style={{
                  padding:      '12px 16px',
                  borderBottom: '1px solid #1e2d47'
                }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#fff' }}>
                    Admin User
                  </div>
                  <div style={{ fontSize: 10, color: '#64748b', marginTop: 2 }}>
                    System Administrator
                  </div>
                  <span style={{
                    fontSize:     9, fontWeight: 700,
                    background:   '#450a0a', color: '#f87171',
                    padding:      '2px 8px', borderRadius: 3,
                    display:      'inline-block', marginTop: 5
                  }}>
                    Admin
                  </span>
                </div>

                {[
                  { icon: '⚙', label: 'Settings', page: 'Settings' },
                  { icon: '📄', label: 'Logs',     page: 'Logs'     },
                  { icon: '🖥', label: 'System',   page: 'System'   },
                ].map((item, i) => (
                  <div
                    key={i}
                    onClick={() => {
                      window.dispatchEvent(
                        new CustomEvent('navigate', { detail: item.page })
                      );
                      setShowMenu(false);
                    }}
                    style={{
                      padding:      '10px 16px',
                      fontSize:     12,
                      color:        '#94a3b8',
                      cursor:       'pointer',
                      display:      'flex',
                      alignItems:   'center',
                      gap:          10,
                      borderBottom: i < 2 ? '1px solid #1e2d47' : 'none',
                      transition:   'background .15s'
                    }}
                    onMouseEnter={e => e.currentTarget.style.background = '#1a2340'}
                    onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                  >
                    <span style={{ fontSize: 15 }}>{item.icon}</span>
                    {item.label}
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Add Camera Button */}
          <button
            onClick={() => setShowModal(true)}
            style={{
              background:    '#3b82f6',
              color:         '#fff',
              border:        'none',
              padding:       '9px 20px',
              borderRadius:  8,
              fontSize:      13,
              fontWeight:    700,
              cursor:        'pointer',
              display:       'flex',
              alignItems:    'center',
              gap:           6,
              letterSpacing: '.3px',
              transition:    'background .2s'
            }}
            onMouseEnter={e => e.currentTarget.style.background = '#2563eb'}
            onMouseLeave={e => e.currentTarget.style.background = '#3b82f6'}
          >
            <span style={{ fontSize: 16, fontWeight: 300 }}>+</span>
            Add Camera
          </button>
        </div>
      </div>

      {showModal && (
        <AddCameraModal onClose={() => setShowModal(false)} />
      )}
    </>
  );
}
